window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aa99edecf6728f01"]={"versions": [{"id": "FIG-aa99edecf6728f01", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das NVRAM-Management in AUTOSAR Classic Platform. Es visualisiert das Prinzip des impliziten Aktualisierens und Wiederherstellens von Datenblöcken (RAM Mirror / RAM blocks) ohne direkte VFB- oder AUTOSAR-Schnittstellenkommunikation zwischen Anwendungs-Software-Komponente und NVRAM Manager. Die RTE ist gestrichelt als logischer Kontext bzw. Vermittler für Zustandswechsel angedeutet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR SW-Component</strong>: Software-Komponente der Anwendungsebene; greift direkt bzw. über RTE-Puffer auf die Dateninhalte zu.\n</li><li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM-Spiegel / RAM mirror), permanent den nichtflüchtigen Pendants zugeordnet.\n</li><li><strong>NVRAM Manager</strong>: Basissoftware-Modul (Services Layer); zuständig für die Verwaltung und Sicherung/Wiederherstellung von/zu NVRAM.\n</li><li><strong>Other parts of basic SW</strong>: Weitere BSW-Module (insbesondere ECU State Manager / EcuM).\n</li><li><strong>RTE</strong>: Runtime Environment (gestrichelt dargestellt); entkoppelt SW-C und BSW, regelt Zustands- und Aktivierungsereignisse.\n</li><li>Schnittstellen/Interaktionspfade:\n<ul class=\"fig-list\"><li>Von SW-C zu RAM block: Unidirektionaler Pfeil „Access content of RAM blocks“.\n</li><li>Von Other parts of basic SW zu NVRAM Manager: Unidirektionaler Steuerpfeil „Initialize; Request to restore/save all blocks depending on ECU state“.\n</li><li>Von NVRAM Manager zu RAM block: Unidirektionaler Pfeil „Restore/save all blocks from/to non-volatile medium“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>BSW-Module („Other parts of basic SW“, typischerweise ECU State Manager) initialisieren den NVRAM Manager und fordern abhängig vom Steuergerätezustand (z. B. Startup oder Shutdown) das globale Wiederherstellen bzw. Speichern aller Blöcke an („Initialize; Request to restore/save all blocks depending on ECU state“).\n</li><li>Der NVRAM Manager überträgt die Blockinhalte zwischen dem nichtflüchtigen Speichermedium und den zugeordneten RAM-Blöcken („Restore/save all blocks from/to non-volatile medium“).\n</li><li>Die AUTOSAR-Softwarekomponente greift unabhängig und ohne NVRAM-Service-Aufrufe direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).\n</li><li>Zwischen NVRAM Manager und SW-Component findet über den RAM-Block kein direkter Informationstransfer statt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht den Kontrakt für den impliziten NVRAM-Zugriff (Implicit RAM mirror):</p>\n<ul class=\"fig-list\"><li>Die Software-Komponente benötigt keine AUTOSAR-Service-Ports zum NvM (<code>NvM_Service</code> / Client-Server-Interface).\n</li><li>Konsistenz und Zugriffsschutz müssen über definierte Systemzustände sichergestellt werden: Die Komponente darf nur in sicheren ECU-Betriebszuständen auf die RAM-Blöcke zugreifen, vermittelt über RTE und EcuM.\n</li><li>Blockidentifikation, Blockgröße und Abbildung müssen zur Konfigurationszeit statisch zwischen NvM und SW-C vereinbart sein.\n</li></ul>"}, {"id": "FIG-9e545e301f94a133", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das NVRAM-Management in AUTOSAR Classic Platform. Es visualisiert das Prinzip des impliziten Aktualisierens und Wiederherstellens von Datenblöcken (RAM Mirror / RAM blocks) ohne direkte VFB- oder AUTOSAR-Schnittstellenkommunikation zwischen Anwendungs-Software-Komponente und NVRAM Manager. Die RTE ist gestrichelt als logischer Kontext bzw. Vermittler für Zustandswechsel angedeutet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR SW-Component</strong>: Software-Komponente der Anwendungsebene; greift direkt bzw. über RTE-Puffer auf die Dateninhalte zu.\n</li><li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM-Spiegel / RAM mirror), permanent den nichtflüchtigen Pendants zugeordnet.\n</li><li><strong>NVRAM Manager</strong>: Basissoftware-Modul (Services Layer); zuständig für die Verwaltung und Sicherung/Wiederherstellung von/zu NVRAM.\n</li><li><strong>Other parts of basic SW</strong>: Weitere BSW-Module (insbesondere ECU State Manager / EcuM).\n</li><li><strong>RTE</strong>: Runtime Environment (gestrichelt dargestellt); entkoppelt SW-C und BSW, regelt Zustands- und Aktivierungsereignisse.\n</li><li>Schnittstellen/Interaktionspfade:\n<ul class=\"fig-list\"><li>Von SW-C zu RAM block: Unidirektionaler Pfeil „Access content of RAM blocks“.\n</li><li>Von Other parts of basic SW zu NVRAM Manager: Unidirektionaler Steuerpfeil „Initialize; Request to restore/save all blocks depending on ECU state“.\n</li><li>Von NVRAM Manager zu RAM block: Unidirektionaler Pfeil „Restore/save all blocks from/to non-volatile medium“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>BSW-Module („Other parts of basic SW“, typischerweise ECU State Manager) initialisieren den NVRAM Manager und fordern abhängig vom Steuergerätezustand (z. B. Startup oder Shutdown) das globale Wiederherstellen bzw. Speichern aller Blöcke an („Initialize; Request to restore/save all blocks depending on ECU state“).\n</li><li>Der NVRAM Manager überträgt die Blockinhalte zwischen dem nichtflüchtigen Speichermedium und den zugeordneten RAM-Blöcken („Restore/save all blocks from/to non-volatile medium“).\n</li><li>Die AUTOSAR-Softwarekomponente greift unabhängig und ohne NVRAM-Service-Aufrufe direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).\n</li><li>Zwischen NVRAM Manager und SW-Component findet über den RAM-Block kein direkter Informationstransfer statt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht den Kontrakt für den impliziten NVRAM-Zugriff (Implicit RAM mirror):</p>\n<ul class=\"fig-list\"><li>Die Software-Komponente benötigt keine AUTOSAR-Service-Ports zum NvM (<code>NvM_Service</code> / Client-Server-Interface).\n</li><li>Konsistenz und Zugriffsschutz müssen über definierte Systemzustände sichergestellt werden: Die Komponente darf nur in sicheren ECU-Betriebszuständen auf die RAM-Blöcke zugreifen, vermittelt über RTE und EcuM.\n</li><li>Blockidentifikation, Blockgröße und Abbildung müssen zur Konfigurationszeit statisch zwischen NvM und SW-C vereinbart sein.\n</li></ul>"}, {"id": "FIG-cdab6dc0d497787b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das NVRAM-Management in AUTOSAR Classic Platform. Es visualisiert das Prinzip des impliziten Aktualisierens und Wiederherstellens von Datenblöcken (RAM Mirror / RAM blocks) ohne direkte VFB- oder AUTOSAR-Schnittstellenkommunikation zwischen Anwendungs-Software-Komponente und NVRAM Manager. Die RTE ist gestrichelt als logischer Kontext bzw. Vermittler für Zustandswechsel angedeutet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR SW-Component</strong>: Software-Komponente der Anwendungsebene; greift direkt bzw. über RTE-Puffer auf die Dateninhalte zu.\n</li><li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM-Spiegel / RAM mirror), permanent den nichtflüchtigen Pendants zugeordnet.\n</li><li><strong>NVRAM Manager</strong>: Basissoftware-Modul (Services Layer); zuständig für die Verwaltung und Sicherung/Wiederherstellung von/zu NVRAM.\n</li><li><strong>Other parts of basic SW</strong>: Weitere BSW-Module (insbesondere ECU State Manager / EcuM).\n</li><li><strong>RTE</strong>: Runtime Environment (gestrichelt dargestellt); entkoppelt SW-C und BSW, regelt Zustands- und Aktivierungsereignisse.\n</li><li>Schnittstellen/Interaktionspfade:\n<ul class=\"fig-list\"><li>Von SW-C zu RAM block: Unidirektionaler Pfeil „Access content of RAM blocks“.\n</li><li>Von Other parts of basic SW zu NVRAM Manager: Unidirektionaler Steuerpfeil „Initialize; Request to restore/save all blocks depending on ECU state“.\n</li><li>Von NVRAM Manager zu RAM block: Unidirektionaler Pfeil „Restore/save all blocks from/to non-volatile medium“.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>BSW-Module („Other parts of basic SW“, typischerweise ECU State Manager) initialisieren den NVRAM Manager und fordern abhängig vom Steuergerätezustand (z. B. Startup oder Shutdown) das globale Wiederherstellen bzw. Speichern aller Blöcke an („Initialize; Request to restore/save all blocks depending on ECU state“).\n</li><li>Der NVRAM Manager überträgt die Blockinhalte zwischen dem nichtflüchtigen Speichermedium und den zugeordneten RAM-Blöcken („Restore/save all blocks from/to non-volatile medium“).\n</li><li>Die AUTOSAR-Softwarekomponente greift unabhängig und ohne NVRAM-Service-Aufrufe direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).\n</li><li>Zwischen NVRAM Manager und SW-Component findet über den RAM-Block kein direkter Informationstransfer statt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild verdeutlicht den Kontrakt für den impliziten NVRAM-Zugriff (Implicit RAM mirror):</p>\n<ul class=\"fig-list\"><li>Die Software-Komponente benötigt keine AUTOSAR-Service-Ports zum NvM (<code>NvM_Service</code> / Client-Server-Interface).\n</li><li>Konsistenz und Zugriffsschutz müssen über definierte Systemzustände sichergestellt werden: Die Komponente darf nur in sicheren ECU-Betriebszuständen auf die RAM-Blöcke zugreifen, vermittelt über RTE und EcuM.\n</li><li>Blockidentifikation, Blockgröße und Abbildung müssen zur Konfigurationszeit statisch zwischen NvM und SW-C vereinbart sein.\n</li></ul>"}], "trans": [{"from": "FIG-aa99edecf6728f01", "to": "FIG-9e545e301f94a133", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e545e301f94a133", "to": "FIG-cdab6dc0d497787b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
